import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/en/canvas-palette.png",d="/relio/shots/en/canvas-arrange-menu.png",p=JSON.parse('{"title":"Canvas and palette","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/canvas.md","filePath":"en/features/canvas.md"}'),r={name:"en/features/canvas.md"};function s(l,t,h,c,b,g){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="canvas-and-palette" tabindex="-1">Canvas and palette <a class="header-anchor" href="#canvas-and-palette" aria-label="Permalink to &quot;Canvas and palette&quot;">​</a></h1><p>Reading the canvas, the palette tools, selecting and moving, the Arrange menu, display settings in the View menu, zoom, pan and panels, and the outline.</p><p>For just the quick ways to get around, see <a href="/relio/en/quick/navigate">Getting around the canvas</a> in Quick start; for the drawing steps, see <a href="/relio/en/quick/draw">Draw tables, columns and relationships</a>.</p><p>The parts of the window (menus, toolbar, palette, outline, status bar) and the word &quot;node&quot; are explained in <a href="/relio/en/features/#the-window">Features › The window</a>.</p><h2 id="reading-the-canvas" tabindex="-1">Reading the canvas <a class="header-anchor" href="#reading-the-canvas" aria-label="Permalink to &quot;Reading the canvas&quot;">​</a></h2><h3 id="table-boxes" tabindex="-1">Table boxes <a class="header-anchor" href="#table-boxes" aria-label="Permalink to &quot;Table boxes&quot;">​</a></h3><ul><li>The table name is in the header, with one line per column below it. Primary key (PK) columns are grouped at the top and separated from the rest by a thin line.</li><li>The <strong>PK</strong> and <strong>FK</strong> badges at the left of a column line mark primary key and foreign key columns. A column that is both gets both badges.</li><li>The data type (for example <code>varchar(100)</code>) appears to the right of the name, and <strong>NN</strong> (NOT NULL) and <strong>UQ</strong> (UNIQUE) appear in small letters at the end of the line.</li><li>Auto increment (AUTO_INCREMENT) columns get a small circled + right after the name. Hover over it to see &quot;Auto increment&quot;.</li><li>Group columns appear as one italic line, <code>≡ group name</code>. Turn on View › Notation level › <strong>Expand groups</strong> to show the columns inside the group.</li><li>Views look like tables, with <code>VIEW</code> at the right of the header.</li><li>A table with no columns shows a faint &quot;Double-click to add columns&quot; hint (not shown in image exports or printing).</li><li>A new, empty document shows &quot;Add table (T)&quot; and how to create the first table faintly in the middle of the canvas; the hint disappears once you create a node.</li></ul><h3 id="notation-level" tabindex="-1">Notation level <a class="header-anchor" href="#notation-level" aria-label="Permalink to &quot;Notation level&quot;">​</a></h3><p>View › Notation level ▸ chooses what the table boxes show.</p><table tabindex="0"><thead><tr><th>Notation level</th><th>What is shown</th></tr></thead><tbody><tr><td>Details</td><td>All columns with PK and FK badges, data types, NN and UQ, and auto increment marks</td></tr><tr><td>Table names only</td><td>Only the table name (no columns)</td></tr><tr><td>Column names</td><td>Only the names of all columns</td></tr><tr><td>Keys only</td><td>Only PK and FK columns and columns referenced by other tables, with badges, data types, NN and UQ</td></tr><tr><td>Detailed (no types)</td><td>Details without the data types</td></tr><tr><td>Column names and keys</td><td>The names of all columns with PK and FK badges</td></tr></tbody></table><h3 id="relationship-line-ends" tabindex="-1">Relationship line ends <a class="header-anchor" href="#relationship-line-ends" aria-label="Permalink to &quot;Relationship line ends&quot;">​</a></h3><p>A relationship line connects the parent (the referenced table) and the child (the table with the foreign key (FK)). The symbols at the line ends show the <strong>cardinality</strong> set in the relationship properties dialog; choose IE or IDEF1X in View › Notation ▸. Note connection lines are dashed lines without symbols.</p><table tabindex="0"><thead><tr><th>Cardinality</th><th>IE</th><th>IDEF1X</th></tr></thead><tbody><tr><td>1 (parent default, child 1)</td><td>One short bar</td><td>One short bar</td></tr><tr><td>0..1</td><td>Bar + open circle</td><td>Parent side: bar + open circle; child side: filled dot + <code>Z</code></td></tr><tr><td>1..n (child default)</td><td>Crow&#39;s foot + bar</td><td>Filled dot + <code>P</code></td></tr><tr><td>0..n</td><td>Crow&#39;s foot + open circle</td><td>Filled dot</td></tr></tbody></table><h2 id="palette-tools" tabindex="-1">Palette tools <a class="header-anchor" href="#palette-tools" aria-label="Permalink to &quot;Palette tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Key</th><th>How to use it</th></tr></thead><tbody><tr><td>Select</td><td><kbd>V</kbd></td><td>Click to select, drag to move, drag on empty space to select several.</td></tr><tr><td>Hand tool</td><td><kbd>H</kbd></td><td>Dragging anywhere on the canvas only moves the view. It stays on after use; end it with <kbd>Esc</kbd> or <kbd>V</kbd> (from 1.0.2).</td></tr><tr><td>Table</td><td><kbd>T</kbd></td><td>Creates a new table where you click.</td></tr><tr><td>View</td><td><kbd>W</kbd></td><td>Creates a new view where you click.</td></tr><tr><td>1:N relationship (one-to-many)</td><td><kbd>R</kbd></td><td>Parent → child. FK columns that follow the parent&#39;s primary key (PK) are created in the child.</td></tr><tr><td>1:N relationship using existing columns</td><td></td><td>Parent → child. Opens a dialog to pick the child&#39;s existing columns as the FK.</td></tr><tr><td>N:M relationship (many-to-many)</td><td></td><td>Click two tables to create an intersection table between them, connected by two 1:N relationships.</td></tr><tr><td>Self-referencing relationship</td><td></td><td>Click one table to create a relationship to itself, with its FK column.</td></tr><tr><td>Note</td><td><kbd>N</kbd></td><td>Creates a note where you click; start typing right away.</td></tr><tr><td>Note connection (dashed line)</td><td></td><td>Click a note, then the target node, to connect them with a dashed line.</td></tr><tr><td>Category</td><td><kbd>C</kbd></td><td>Drag to make an area. Nodes inside the area belong to that category.</td></tr><tr><td>Insert image</td><td></td><td>Pick an image file (bmp, jpg, jpeg, gif, png) to insert. The image is stored inside the file, so large images make the file large.</td></tr></tbody></table><ul><li>After one use, a tool returns to Select. Hold <kbd>Shift</kbd> while using it to keep the same tool and create several in a row. The hand tool always stays on.</li><li>With a relationship tool, click the first table and then the second, or drag from the first table and drop on the second. Clicking empty space or pressing <kbd>Esc</kbd> cancels. Clicking the same table twice with the 1:N relationship tool creates a self-referencing relationship.</li><li><strong>Creating a relationship with the keyboard only</strong> — Press <kbd>Tab</kbd> to move focus to the parent table, <kbd>R</kbd> to pick the relationship tool, and <kbd>Enter</kbd> to set the parent. Then <kbd>Tab</kbd> to the child table and press <kbd>Enter</kbd> to create the relationship.</li><li>If the parent has no primary key, Relio says &quot;No columns to reference — the parent table has no primary key.&quot;</li><li>New tables are named in the app language (in English, logical name &quot;New table&quot; and physical name <code>NEW_TABLE</code>).</li></ul><figure class="shot" data-scene="canvas-palette"><img src="'+i+'" alt="Palette — select, hand, table, view, four relationship tools, note, note connection, category and insert image" loading="lazy"><figcaption>Palette — select, hand, table, view, four relationship tools, note, note connection, category and insert image</figcaption></figure><h2 id="selecting-and-moving" tabindex="-1">Selecting and moving <a class="header-anchor" href="#selecting-and-moving" aria-label="Permalink to &quot;Selecting and moving&quot;">​</a></h2><ul><li><strong>Select</strong> — Click; <kbd>Shift</kbd>+click (or <kbd>Ctrl</kbd>+click) to add or remove; drag on empty space to select a range. <kbd>Esc</kbd> clears the selection.</li><li><strong>Move</strong> — Drag, or use the arrow keys to move by 1 and <kbd>Shift</kbd>+arrow keys to move by 10. While dragging, alignment guides appear at the edges and centers of other nodes.</li><li><strong>Size</strong> — Select a table or view and drag the left or right handle to change its width. You can widen it freely and narrow it down to the width that still shows all its content. The height always fits the number of columns. Notes, images and categories are resized with their handles.</li><li><strong>Rename in place</strong> — <kbd>F2</kbd>. Edits a table&#39;s physical name or a note&#39;s text in place. The field stays open even if you switch to another program and come back, so you can keep typing.</li><li><strong>Properties dialog</strong> — Double-click or <kbd>Enter</kbd>. <a href="/relio/en/features/dialogs">Properties dialogs</a></li><li><strong>Move focus</strong> — <kbd>Tab</kbd> / <kbd>Shift</kbd>+<kbd>Tab</kbd> go to the next and previous node.</li></ul><h3 id="what-double-click-opens" tabindex="-1">What double-click opens <a class="header-anchor" href="#what-double-click-opens" aria-label="Permalink to &quot;What double-click opens&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Target</th><th>Opens</th></tr></thead><tbody><tr><td>Table</td><td>Table properties dialog (double-clicking a column line opens it with that column selected)</td></tr><tr><td>View</td><td>View properties dialog</td></tr><tr><td>Relationship line</td><td>Relationship properties dialog</td></tr><tr><td>Note</td><td>Edit the text in place (click outside to confirm)</td></tr><tr><td>Note connection line</td><td>Connection properties dialog (line color)</td></tr><tr><td>Stamp</td><td>Model properties dialog — <a href="/relio/en/features/model#model-properties">Model menu › Model properties</a></td></tr><tr><td>Image</td><td>Image properties dialog</td></tr><tr><td>Category area</td><td>Rename the category in place</td></tr></tbody></table><h3 id="working-with-columns-on-the-canvas" tabindex="-1">Working with columns on the canvas <a class="header-anchor" href="#working-with-columns-on-the-canvas" aria-label="Permalink to &quot;Working with columns on the canvas&quot;">​</a></h3><ul><li>Click a column inside a table to select that column. Turn on View › <strong>Disable column clicks</strong> to select only whole tables.</li><li>Drag a selected column to reorder it within the same table, or drop it on another table to move it there. Hold <kbd>Ctrl</kbd> while dropping to copy instead of move.</li><li>Columns referenced by other tables cannot be moved. Moving an FK column to another table recreates the relationship so that table becomes the child.</li><li>Group columns move as a group; select a group and press <kbd>Delete</kbd> to remove the group from the table.</li><li>Drag a word or group from the outline onto a table on the canvas to add it as a column (group).</li></ul><h3 id="connection-lines" tabindex="-1">Connection lines <a class="header-anchor" href="#connection-lines" aria-label="Permalink to &quot;Connection lines&quot;">​</a></h3><ul><li>Drag a relationship line to add a bend point, drag a bend point to move it, and double-click a bend point to remove it.</li><li>Drag the end of a relationship line to another spot on the same table&#39;s border. Drop it toward the middle of the table to return it to the automatic position.</li><li>Relationship names are not drawn on the line. Select a relationship line to see its name in a tooltip.</li></ul><h2 id="arrange-menu" tabindex="-1">Arrange menu <a class="header-anchor" href="#arrange-menu" aria-label="Permalink to &quot;Arrange menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu › Item</th><th>Available when</th><th>What it does</th></tr></thead><tbody><tr><td>Arrange › Align left · Align center · Align right</td><td>2 or more nodes</td><td>Aligns left edges, centers or right edges to the node <strong>selected last</strong>.</td></tr><tr><td>Arrange › Align top · Align middle (vertical) · Align bottom</td><td>2 or more nodes</td><td>Aligns tops, middles or bottoms to the node selected last.</td></tr><tr><td>Arrange › Fit width · Fit height</td><td>2 or more nodes</td><td>Makes the width or height the same as the node <strong>selected first</strong>. Table and view heights always fit their content, so Fit height does not change them.</td></tr><tr><td>Arrange › Distribute horizontally · Distribute vertically</td><td>3 or more tables or notes</td><td>Spaces the rest evenly between the two outermost nodes.</td></tr><tr><td>Arrange › Auto size</td><td>Tables, views, notes</td><td>Returns them to the size that fits their content.</td></tr><tr><td>Arrange › Right-angle connectors</td><td>Connection lines</td><td>Redraws the path with horizontal and vertical segments.</td></tr><tr><td>Arrange › Restore defaults</td><td>Connection lines, or nodes they leave from</td><td>Removes bend points and returns both ends to their automatic positions. With a node selected, it applies to the lines leaving that node (including note connection lines from a note, but not self-referencing relationships).</td></tr><tr><td>Arrange › Tidy connection lines</td><td>Connection lines, or tables they are attached to</td><td>Tidies the bend points and ends of the selected lines and of every line attached to the selected nodes.</td></tr><tr><td>Arrange › Background color</td><td>Nodes or connection lines</td><td>Paints the selection with the current color. The current color appears next to the menu item, like <code>(#1E90FF)</code>. Picking a color from the toolbar&#39;s Background color ▼ makes it the current color.</td></tr><tr><td>Arrange › Font ▸ · Font size ▸</td><td>Nodes</td><td>Changes the font and size of the selected nodes.</td></tr></tbody></table><p>The node used as the alignment reference has a stronger selection outline. The toolbar&#39;s <strong>Align ▾</strong> repeats the last alignment when you click its main part; click ▾ to choose from the six alignments, Fit width or Fit height, and horizontal or vertical distribution. When there is nothing to change (for example a line that is already tidy), only a hint appears in the status bar and the document is not changed.</p><figure class="shot" data-scene="canvas-arrange-menu"><img src="'+d+'" alt="Arrange menu — three tables selected with the align and distribute items open" loading="lazy"><figcaption>Arrange menu — three tables selected with the align and distribute items open</figcaption></figure><h2 id="view-menu" tabindex="-1">View menu <a class="header-anchor" href="#view-menu" aria-label="Permalink to &quot;View menu&quot;">​</a></h2><h3 id="display-settings-saved-in-the-document" tabindex="-1">Display settings saved in the document <a class="header-anchor" href="#display-settings-saved-in-the-document" aria-label="Permalink to &quot;Display settings saved in the document&quot;">​</a></h3><p>These settings are saved in the <code>.erm</code> document; changing them marks the document as changed and can be undone. The same items are in canvas right-click › Document › Show ▸.</p><table tabindex="0"><thead><tr><th>Menu › Item</th><th>Values</th></tr></thead><tbody><tr><td>View › View mode ▸</td><td>Logical name · Physical name · Logical/physical name — which name nodes show</td></tr><tr><td>View › Notation ▸</td><td>IE · IDEF1X — the relationship line end symbols</td></tr><tr><td>View › Notation level ▸</td><td>Details · Table names only · Column names · Keys only · Detailed (no types) · Column names and keys, plus <strong>Expand groups</strong></td></tr><tr><td>View › Design ▸</td><td>funny — rounded cards · frame — double border · simple — lines</td></tr><tr><td>View › Show in upper case</td><td>Shows names in upper case.</td></tr><tr><td>View › Show stamp</td><td>Shows the model properties table (project name, model name, version and so on) at the top left of the canvas.</td></tr><tr><td>View › Curved connectors</td><td>Draws relationship lines as curves.</td></tr></tbody></table><p>When the logical and physical names are the same, the name is drawn once.</p><h3 id="view-settings-remembered-on-this-pc" tabindex="-1">View settings remembered on this PC <a class="header-anchor" href="#view-settings-remembered-on-this-pc" aria-label="Permalink to &quot;View settings remembered on this PC&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu › Item</th><th>Shortcut</th><th>What it does</th></tr></thead><tbody><tr><td>View › Show design check marks</td><td></td><td>Turns the check marks on the canvas on or off. <a href="/relio/en/features/check">Design check and suggestions</a></td></tr><tr><td>View › Show info marks on canvas</td><td></td><td>Also draws info findings on the canvas.</td></tr><tr><td>View › Zoom in · Zoom out · 100%</td><td><kbd>Ctrl</kbd>+<kbd>=</kbd> · <kbd>Ctrl</kbd>+<kbd>-</kbd> · <kbd>Ctrl</kbd>+<kbd>0</kbd></td><td>Changes the zoom level.</td></tr><tr><td>View › Fit all · Fit height · Fit width</td><td></td><td>Fits the whole diagram (or its height or width) in the window.</td></tr><tr><td>View › Grid · Snap to grid</td><td></td><td>Shows the grid and places nodes on it (both on by default).</td></tr><tr><td>View › Relationship drawing labels</td><td></td><td>While drawing a relationship, shows a name label above the table under the mouse.</td></tr><tr><td>View › Disable column clicks</td><td></td><td>Prevents selecting individual columns inside tables. When on, it shows in small text in the status bar.</td></tr><tr><td>View › Panels ▸</td><td></td><td>Palette, Right panel (Outline), Bottom panel (Problem list), Maximize canvas.</td></tr><tr><td>View › Start screen</td><td></td><td>Shows the start screen while documents stay open.</td></tr></tbody></table><h2 id="zoom-and-pan" tabindex="-1">Zoom and pan <a class="header-anchor" href="#zoom-and-pan" aria-label="Permalink to &quot;Zoom and pan&quot;">​</a></h2><ul><li><strong>Zoom in and out</strong> — <kbd>Ctrl</kbd>+mouse wheel (around the mouse pointer), <kbd>Ctrl</kbd>+<kbd>=</kbd> · <kbd>Ctrl</kbd>+<kbd>-</kbd> · <kbd>Ctrl</kbd>+<kbd>0</kbd>, or the zoom list on the toolbar.</li><li><strong>Move the view</strong> — Hold <kbd>Space</kbd> and drag (release to return to your tool), the hand tool (<kbd>H</kbd>), drag with the middle mouse button, scroll with two fingers on a touchpad, or drag the rectangle in the minimap. While you are typing text, <kbd>Space</kbd> types a space.</li><li>Below 40% zoom, nodes are drawn as simple boxes with just their names and category names are shown large, like a map. Image exports and printing always use the normal look.</li><li>The zoom level and view position are saved in the document.</li></ul><h2 id="panels-and-the-start-screen" tabindex="-1">Panels and the start screen <a class="header-anchor" href="#panels-and-the-start-screen" aria-label="Permalink to &quot;Panels and the start screen&quot;">​</a></h2><ul><li>Collapse and expand the <strong>right panel</strong> (outline and minimap) with <kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>B</kbd> and the <strong>bottom panel</strong> (problem list) with <kbd>Ctrl</kbd>+<kbd>J</kbd>. The two buttons at the right end of the document tab bar and View › Panels ▸ do the same.</li><li><strong>Maximize canvas</strong> — Double-click a document tab or press <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>M</kbd> to collapse both panels at once; do it again to return to how they were. The palette is not collapsed.</li><li>The collapsed state is kept the next time you start Relio.</li><li><strong>Start screen</strong> — View › Start screen shows the start screen with new, open, samples and recent files. Open documents stay open; click a tab, press <kbd>Esc</kbd> or click <strong>Back to open documents</strong> to return. While the start screen is shown, the document menus and editing shortcuts are off.</li></ul><h2 id="outline" tabindex="-1">Outline <a class="header-anchor" href="#outline" aria-label="Permalink to &quot;Outline&quot;">​</a></h2><ul><li>Type in the <strong>Find by name</strong> field at the top to filter the lists.</li><li>Click a table or view to expand its columns (group columns show as one line with the group name) and, for tables, its indexes.</li><li>Double-click an item to open its dialog: word → Word properties; group → Manage groups; index, sequence, trigger or tablespace → its properties dialog; table or view → goes to that node on the canvas, selects it and opens its properties dialog; column → opens the table properties dialog with that column selected.</li><li>Drag words and groups onto a table on the canvas to add them as columns.</li><li>Right-click for: Delete, Manage groups, Add trigger · Add sequence · Add index · Add tablespace (only those that fit the selected kind), <strong>Outline view mode</strong> (Logical name · Physical name · Logical+physical name) and <strong>Sort by</strong> (Logical name · Physical name).</li><li>Rows with a count of 0 are dimmed, and <strong>+ Add</strong> creates the first item right away. Sequences and tablespaces can be added only when the database (version) supports them.</li></ul>',42)])])}const u=e(r,[["render",s]]);export{p as __pageData,u as default};
